export function Anchor({
  skipLabel = "{{skipLabel}}",
  sectionLabel = "{{sectionLabel}}",
  accent = "{{accent}}",
  style = "{{style}}",
}) {
  const linkStyle = style === "pill"
    ? { textDecoration: "none", background: accent, padding: "2px 8px", borderRadius: 999 }
    : { textDecoration: "underline", textDecorationColor: accent, textDecorationThickness: 2 };
  return (
    <div style={{ position: "relative", paddingTop: 4, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <a href="#anchor-target" style={{ position: "absolute", left: -9999, top: 0, background: "#241430", color: "#FAF7F2", padding: "8px 14px", borderRadius: 8, textDecoration: "none", fontWeight: 600 }}>{skipLabel}</a>
      <p style={{ margin: "0 0 10px", lineHeight: 1.6 }}>Read the overview, then <a href="#pricing" style={{ color: "#241430", ...linkStyle }}>{sectionLabel}</a> further down the page.</p>
      <div id="anchor-target" tabIndex={-1} style={{ padding: 10, border: "1px dashed rgba(36,20,48,.3)", borderRadius: 8, fontSize: 12, opacity: .6 }}>Main content landmark</div>
    </div>
  );
}
